CREATE TABLE public.studies (id text PRIMARY KEY, osdr_accession text NOT NULL UNIQUE, title text NOT NULL, description text NOT NULL, organism text, tissue text, experimental_conditions text, data_types text[], source_url text NOT NULL, verification_status text NOT NULL DEFAULT 'Not yet verified', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.studies TO anon, authenticated; GRANT ALL ON public.studies TO service_role;
ALTER TABLE public.studies ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public study references" ON public.studies FOR SELECT TO anon, authenticated USING (true);
INSERT INTO public.studies (id,osdr_accession,title,description,source_url) VALUES ('OSD-324','OSD-324','Osteocyte-related spaceflight research','Bone biology reference supplied in the product brief. Study title, model, tissue and experimental conditions have not yet been independently verified.','https://osdr.nasa.gov/bio/repo/data/studies/OSD-324'),('OSD-238','OSD-238','Mouse skin spaceflight research','Skin biology reference supplied in the product brief. Study title, model, tissue and experimental conditions have not yet been independently verified.','https://osdr.nasa.gov/bio/repo/data/studies/OSD-238');
CREATE TABLE public.analyses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), study_id text NOT NULL REFERENCES public.studies(id), analysis_name text NOT NULL, analysis_type text NOT NULL, methodology text NOT NULL, source_file text NOT NULL, source_url text NOT NULL, processing_status text NOT NULL DEFAULT 'Imported • user supplied', results jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.analyses TO authenticated; GRANT ALL ON public.analyses TO service_role;
ALTER TABLE public.analyses ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own analyses" ON public.analyses FOR ALL TO authenticated USING (owner_id=auth.uid()) WITH CHECK (owner_id=auth.uid());
CREATE INDEX analyses_owner_study ON public.analyses(owner_id,study_id);
CREATE TABLE public.candidate_measurements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.candidate_measurements TO authenticated; GRANT ALL ON public.candidate_measurements TO service_role;
ALTER TABLE public.candidate_measurements ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own candidates" ON public.candidate_measurements FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE INDEX candidates_owner ON public.candidate_measurements(owner_id);
CREATE TABLE public.references (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.references TO authenticated; GRANT ALL ON public.references TO service_role;
ALTER TABLE public.references ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own references" ON public.references FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE INDEX references_owner ON public.references(owner_id);
CREATE TABLE public.roadmap_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.roadmap_items TO authenticated; GRANT ALL ON public.roadmap_items TO service_role;
ALTER TABLE public.roadmap_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own roadmap" ON public.roadmap_items FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE INDEX roadmap_owner ON public.roadmap_items(owner_id);
CREATE TABLE public.research_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.research_notes TO authenticated; GRANT ALL ON public.research_notes TO service_role;
ALTER TABLE public.research_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own notes" ON public.research_notes FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE INDEX notes_owner ON public.research_notes(owner_id);
CREATE TABLE public.evidence_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), reference_id uuid NOT NULL REFERENCES public.references(id) ON DELETE CASCADE, target_type text NOT NULL, target_id text NOT NULL, evidence_note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.evidence_links TO authenticated; GRANT ALL ON public.evidence_links TO service_role;
ALTER TABLE public.evidence_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own evidence" ON public.evidence_links FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid() AND EXISTS(SELECT 1 FROM public.references r WHERE r.id=reference_id AND r.owner_id=auth.uid()));
CREATE INDEX evidence_owner_target ON public.evidence_links(owner_id,target_type,target_id);